import{_ as e,o as a,c as o,a3 as n}from"./chunks/framework.B5WAEDB7.js";const p=JSON.parse('{"title":"Embedding views and evaluations","description":"Show Grid views, metrics, and charts on a page.","frontmatter":{"title":"Embedding views and evaluations","description":"Show Grid views, metrics, and charts on a page."},"headers":[],"relativePath":"en/seiten/auswertungen.md","filePath":"en/seiten/auswertungen.md","lastUpdated":1788108473000}'),s={name:"en/seiten/auswertungen.md"};function i(r,t,l,d,h,c){return a(),o("div",null,[...t[0]||(t[0]=[n(`<h1 id="embedding-views-and-evaluations" tabindex="-1">Embedding views and evaluations <a class="header-anchor" href="#embedding-views-and-evaluations" aria-label="Permalink to &quot;Embedding views and evaluations&quot;">​</a></h1><p>These blocks bring data from your Grids onto the page — as a table, a metric, or a chart.</p><hr><h2 id="grid-view" tabindex="-1">Grid View <a class="header-anchor" href="#grid-view" aria-label="Permalink to &quot;Grid View&quot;">​</a></h2><p>Embeds an existing <a href="/en/ansichten/was-ist-eine-ansicht">view</a>. The most important block for Portals.</p><p>Select it via <em>Set the Grid view</em> → <strong>Select view</strong>.</p><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Show full width</strong></td><td>Spans the entire page width</td></tr><tr><td><strong>Show search</strong></td><td>Search field for visitors</td></tr><tr><td><strong>Show filter</strong></td><td>Filter for visitors</td></tr><tr><td><strong>Show CSV download</strong></td><td>Export for visitors</td></tr><tr><td><strong>Entries read only</strong></td><td>Prevents editing</td></tr><tr><td><strong>Don&#39;t open detail view</strong></td><td>Clicking a row opens nothing</td></tr><tr><td><strong>Hide title</strong></td><td>Hides the view&#39;s title</td></tr><tr><td><strong>Button color</strong></td><td>Color of the controls</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Set both switches for a display-only Portal</p><p><em>Entries read only</em> alone isn&#39;t enough — visitors can still get into an entry&#39;s detail view and see <strong>all</strong> its fields there, including ones hidden in the view.</p><p>Also set <strong>Don&#39;t open detail view</strong>.</p></div><div class="warning custom-block"><p class="custom-block-title">Enable CSV download deliberately</p><p>With <em>Show CSV download</em> active, visitors can download the entire visible dataset — not just view it. For personal data, leave this off.</p></div><div class="tip custom-block"><p class="custom-block-title">A dedicated view for the Portal</p><p>Don&#39;t embed your working view. Create a copy, hide internal columns, and filter it down to what should be shared. That way the Portal doesn&#39;t accidentally change when you adjust something internally.</p></div><hr><h2 id="counter" tabindex="-1">Counter <a class="header-anchor" href="#counter" aria-label="Permalink to &quot;Counter&quot;">​</a></h2><blockquote><p><em>Count the number of entries in a view</em></p></blockquote><p>Shows a single number. It&#39;s based on a view — that view&#39;s filter determines what gets counted.</p><div class="tip custom-block"><p class="custom-block-title">The filter makes the metric</p><p>A counter on an unfiltered view just shows &quot;how many entries exist.&quot; It gets interesting with a filter: &quot;open inquiries,&quot; &quot;overdue tasks,&quot; &quot;new signups this month.&quot;</p><p>Create a dedicated, appropriately filtered view for each metric.</p></div><hr><h2 id="sum-card" tabindex="-1">Sum card <a class="header-anchor" href="#sum-card" aria-label="Permalink to &quot;Sum card&quot;">​</a></h2><blockquote><p><em>Sums the values of a numeric column in a view</em></p></blockquote><p>Setting: <strong>Column to sum</strong>.</p><p>Messages:</p><table tabindex="0"><thead><tr><th>Message</th><th>Meaning</th></tr></thead><tbody><tr><td><em>This view has no summable numeric columns</em></td><td>There&#39;s no column of type Number, Decimal, or Currency — or it&#39;s hidden in the view</td></tr><tr><td><em>This view has more than {maxRows} rows. The sum only covers the first {maxRows} rows.</em></td><td>The sum is <strong>incomplete</strong></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Sums are incomplete on large views</p><p>Past a certain row count, the block only sums the beginning of the view — and still displays a number.</p><p>For reliable totals, use a <a href="/en/ansichten/filtern-sortieren-gruppieren">grouping with aggregate</a> instead, or a field of type <a href="/en/grids/berechnete-felder">Calculate sum</a>.</p></div><hr><h2 id="donut-chart" tabindex="-1">Donut chart <a class="header-anchor" href="#donut-chart" aria-label="Permalink to &quot;Donut chart&quot;">​</a></h2><blockquote><p><em>Shows the distribution of values in a single-select column</em></p></blockquote><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Single select</strong></td><td>The column to evaluate</td></tr><tr><td><strong>Show legend</strong></td><td>Labels for the segments</td></tr><tr><td><strong>Change title</strong></td><td>Custom chart title</td></tr></tbody></table><p>For the title: <em>Override the chart title. Leave empty to use the column name.</em></p><p>Values outside the defined options appear as <strong>Other</strong>.</p><p>Without a matching column: <em>This view has no column of type Single select</em>.</p><div class="tip custom-block"><p class="custom-block-title">Single select only</p><p>Multiple select, text, and numbers don&#39;t work. To evaluate something else, create a Single select column that captures the categorization you want.</p></div><hr><h2 id="timeline-forecast" tabindex="-1">Timeline forecast <a class="header-anchor" href="#timeline-forecast" aria-label="Permalink to &quot;Timeline forecast&quot;">​</a></h2><blockquote><p><em>Compares planned dates with current and previous estimates</em></p></blockquote><table tabindex="0"><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Milestones</strong></td><td>Column with the labels</td></tr><tr><td><strong>Latest estimate</strong></td><td>Column with the current status</td></tr></tbody></table><p>The display distinguishes between <strong>Plan</strong> and <strong>Current estimate</strong>. Without a label, entries are called <em>Milestone</em>.</p><p>Messages: <em>This view has no date columns</em>, <em>This view has no rows</em>, <em>No valid date values were found</em>. A row limit applies here too.</p><hr><h2 id="grid-list" tabindex="-1">Grid List <a class="header-anchor" href="#grid-list" aria-label="Permalink to &quot;Grid List&quot;">​</a></h2><blockquote><p><em>Create a list based on entries from a Grid</em></p></blockquote><p>Unlike the Grid view, here you design the appearance of <strong>each list item yourself</strong>: you select a Grid (<em>Select Grid</em>) and build a template block that repeats per entry (<em>Edit list item</em>).</p><div class="tip custom-block"><p class="custom-block-title">When a table doesn&#39;t fit</p><p>For Portals that shouldn&#39;t look like a table — job listings, events, product listings — this block is the alternative. You can arrange images, headings, and buttons freely.</p><p>Building it takes longer than the Grid view — in exchange you control the design completely. For purely internal overviews, the Grid view is usually the faster route.</p></div><hr><h2 id="button-and-qr-code" tabindex="-1">Button and QR code <a class="header-anchor" href="#button-and-qr-code" aria-label="Permalink to &quot;Button and QR code&quot;">​</a></h2><p>Both point to a form or a Flow.</p><h3 id="button" tabindex="-1">Button <a class="header-anchor" href="#button" aria-label="Permalink to &quot;Button&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Options</th></tr></thead><tbody><tr><td><strong>Link</strong></td><td>The target — <em>Select link</em></td></tr><tr><td><strong>Open</strong></td><td><em>Open on this page</em> / <em>Open in new tab</em></td></tr><tr><td><strong>After submitting</strong></td><td><em>Keep form open</em> / <em>Close after 3 seconds</em> / <em>Close after 5 seconds</em></td></tr><tr><td><strong>Change button title</strong></td><td>Label</td></tr><tr><td><strong>Prefill form</strong></td><td>Preset values</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">&quot;Open on this page&quot; feels more integrated</p><p>The form then appears within the Portal itself instead of a new tab. Combined with <em>Close after 3 seconds</em>, you get a smooth flow: click button, fill out, submit, back to the page.</p></div><p>→ <a href="/en/formulare/vorausgefuellte-links">Prefilled links</a></p><h3 id="qr-code" tabindex="-1">QR code <a class="header-anchor" href="#qr-code" aria-label="Permalink to &quot;QR code&quot;">​</a></h3><p>The same target as a QR code — for posters and printed material.</p><hr><h2 id="building-a-dashboard" tabindex="-1">Building a dashboard <a class="header-anchor" href="#building-a-dashboard" aria-label="Permalink to &quot;Building a dashboard&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vertical layout</span></span>
<span class="line"><span>├── Heading 1                    &quot;Order status&quot;</span></span>
<span class="line"><span>├── Horizontal layout            (Wrap content)</span></span>
<span class="line"><span>│   ├── Counter                  view &quot;open orders&quot;</span></span>
<span class="line"><span>│   ├── Sum card                 view &quot;open orders&quot;, column Amount</span></span>
<span class="line"><span>│   └── Donut chart              view &quot;all orders&quot;, column Status</span></span>
<span class="line"><span>└── Grid View                    view &quot;open orders&quot;</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">One view per metric</p><p>Every evaluation block refers to <strong>one</strong> view. For four metrics, you may need four differently filtered views. Give them descriptive names — otherwise the dashboard becomes hard to maintain later.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/seiten/layout-bloecke">Layout blocks</a></li><li><a href="/en/referenz/blocktypen">Block types reference</a></li><li><a href="/en/seiten/portal-veroeffentlichen">Publishing a Portal</a></li></ul>`,57)])])}const m=e(s,[["render",i]]);export{p as __pageData,m as default};
